"""Integration assertion against a manifest actually generated by dbt in CI."""
import argparse
import json
from pathlib import Path
from datamesh_release_protocol.dependency_import import import_manifest, impact_paths

parser = argparse.ArgumentParser()
parser.add_argument('--manifest', type=Path, required=True)
parser.add_argument('--output', type=Path, required=True)
args = parser.parse_args()
manifest = json.loads(args.manifest.read_text())
bindings = {'seed.dmrp_import.transactions': 'transactions',
            'model.dmrp_import.spending': 'spending_activity_profile',
            'model.dmrp_import.aggregate': 'retail-aggregate',
            'model.dmrp_import.retail': 'retail-offers'}
result = import_manifest(manifest, 'ci:generated-dbt-manifest', bindings)
edges = sorted((edge['producer'], edge['consumer']) for edge in result['observations'])
expected = sorted([('transactions', 'spending_activity_profile'),
                   ('spending_activity_profile', 'retail-aggregate'), ('retail-aggregate', 'retail-offers')])
assert edges == expected, (edges, expected)
assert not result['gaps'], result['gaps']
assert len(impact_paths(result['observations'], 'transactions')['paths']['retail-offers']) == 3
args.output.parent.mkdir(parents=True, exist_ok=True)
args.output.write_text(json.dumps(dict(dbt_version=manifest['metadata']['dbt_version'],
                                     actual_manifest_import=result, matched_expected_edges=True), indent=2) + '\n')
print(json.dumps(dict(dbt_version=manifest['metadata']['dbt_version'], observed_edges=len(edges), matched=True)))
